{
  "title": "黑夜迷宫",
  "scene": "玩家正在一座被霓虹灯点缀的赛博朋克都市中穿梭。街道上人来人往，闪烁着各种广告牌和信息屏幕。前方是一座破旧的仓库，门半开着，里面透出昏暗的灯光。玩家听到里面传来轻微的机械声和低语。",
  "goal": "探索仓库内部，寻找稀有的数据芯片。",
  "choices": [
    {
      "id": "A",
      "text": "推开门，小心翼翼地走进去。",
      "outcome": "玩家走进昏暗的仓库，发现里面布满了灰尘和废弃的机器。突然，一个身影闪过，玩家听到轻微的机器声。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "先关闭仓库的电子门，确保不会有人打扰自己。",
      "outcome": "玩家找到一个控制面板，成功关闭了仓库的电子门。但是，仓库内部的机械装置开始发出异常的声音。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "绕开仓库，寻找其他进入仓库的方法。",
      "outcome": "玩家发现窗户破碎，可以从窗外进入仓库。不过窗户外面是高高的围墙，需要攀爬。",
      "result": "fail",
      "next": "bad_end"
    }
  ]
}
